// =============================================================================
// File           : ApplicationUser.cs
// Layer          : Infrastructure / Identity
// Purpose        : The login account stored in the Users table (ASP.NET Core Identity user + CardioSense fields).
// Logic          : Identity owns e-mail, password hash and lockout; this class adds the role (which decides the profile
//                  table to join and the authorization rules), the preferred language and the creation time.
// Implementation : Sealed subclass of IdentityUser<Guid>; the Guid id is generated by IdentityService (version 7) so
//                  profile rows can reference it before any database round-trip.
// =============================================================================
using CardioSense.Application.Common.Contracts;
using CardioSense.Domain.Enums;
using Microsoft.AspNetCore.Identity;

namespace CardioSense.Infrastructure.Identity;

/// <summary>A login account.</summary>
public sealed class ApplicationUser : IdentityUser<Guid>
{
    /// <summary>Patient or Doctor.</summary>
    public UserRole Role { get; set; }

    /// <summary>Preferred interface language ('ar' or 'en').</summary>
    public string PreferredLanguage { get; set; } = ContractLiterals.Languages.Arabic;

    /// <summary>When the account was created.</summary>
    public DateTimeOffset CreatedAt { get; set; }
}
